def solve(data):
    winners = {}
    for position, event in enumerate(data['events']):
        if 'id' in event:
            identity = ('id', event['id'])
        else:
            identity = ('anonymous', position)

        revision = event.get('revision', 0)
        previous = winners.get(identity)
        if previous is None or revision >= previous[0]:
            winners[identity] = (revision, position)

    winning_positions = {position for _, position in winners.values()}
    balances = {}
    for position, event in enumerate(data['events']):
        if position not in winning_positions:
            continue
        key = f"{event.get('account', 'default')}|{event.get('currency', 'USD')}"
        balances.setdefault(key, 0)
        balances[key] += amount(event, data.get('rounding'))

    return {'balances': balances}
